class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        ListNode *dummy = new ListNode(0);
        ListNode *curr = dummy;
        int carry = 0;

        while(l1 != NULL || l2 != NULL || carry == 1){
            int sum = 0;
            if(l1 != NULL){
                sum += l1->val;
                l1 = l1->next;
            }
            if(l2 != NULL){
                sum += l2->val;
                l2 = l2->next;
            }
            sum += carry;
            carry = sum/10;
            ListNode *node = new ListNode(sum % 10);
            curr->next = node;
            curr = curr->next;
        }
        return dummy->next;
    }
};,3,https://leetcode.com/problems/add-two-numbers,https://leetcode.com/problems/add-two-numbers/solutions/1835535/java-c-a-very-beautiful-explanation-ever-exists/,1,2,cpp

class Solution {
    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        ListNode dH = new ListNode(-1);
        ListNode newHead = dH;
        int carry = 0;

        while(l1!=null || l2!=null) {
            int a = l1 == null ? 0 : l1.val;
            int b = l2 == null ? 0 : l2.val;

            if(l1!=null) l1 = l1.next;
            if(l2!=null) l2 = l2.next;

            int sum = a + b + carry;
            carry = sum/10;

            ListNode newNode = new ListNode(sum%10);
            dH.next = newNode;
            dH = newNode;
        }

        if(carry!=0) {
            dH.next = new ListNode(carry);
        }
        return newHead.next;
    }
