class Solution {
private:
    // Recursive helper function to find combinations that sum up to the target.
    void ans(vector<vector<int>>& res, vector<int>& curr, vector<int>& candidates, int& target, int curr_sum, int i) {
        // If the current sum is equal to the target, add the current combination to the result.
        if (curr_sum == target) {
            res.push_back(curr);
            return;
        }
        // If the current sum exceeds the target or we have processed all the candidates, return.
        if (i >= candidates.size() || curr_sum > target) {
            return;
        }

        // Add the current candidate to the current combination.
        curr.push_back(candidates[i]);
        // Recursively find combinations with the current candidate.
        ans(res, curr, candidates, target, curr_sum + candidates[i], i);
        // Remove the last added candidate to backtrack and try other combinations.
        curr.pop_back();

        // Check if i+1 is a valid index before recursively exploring combinations without the current candidate.
        if (i + 1 < candidates.size()) {
            ans(res, curr, candidates, target, curr_sum, i + 1);
        }
    }
public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        vector<vector<int>> res;
        vector<int> curr;
        ans(res, curr, candidates, target, 0, 0);

        return res;
    }
};,59,https://leetcode.com/problems/combination-sum,https://leetcode.com/problems/combination-sum/solutions/3681254/c-well-comented-easy-to-understand-backtracking/,15,39,cpp

class Solution {
    public int trap(int[] height) {
        int N = height.length;
        int[] left = new int[N], right = new int[N];
        left[0] = height[0];
        right[N-1] = height[N-1];
        for(int i = 1; i < N; i++) {
            left[i] = Math.max(left[i-1], height[i]);
            int j = N - i - 1;
            right[j] = Math.max(right[j+1], height[j]);
        }
        int trappedWater = 0;
        for(int i = 0; i < N; i++) {
            trappedWater+= Math.min(left[i], right[i]) - height[i];
        }
        return trappedWater;
    }
},20,https://leetcode.com/problems/trapping-rain-water,https://leetcode.com/problems/trapping-rain-water/solutions/4410401/clean-java-solution/,16,42,java

class Solution {
public:
    string multiply(string& A, string& B) {
        if(A == "0" || B == "0") return "0";
        string ans(size(A)+size(B), '0');
        for(int i = size(A)-1; i >= 0; i--) {
            for(int j = size(B)-1; j >= 0; j--) {
                int res = (ans[i+j+1]-'0') + (A[i]-'0') * (B[j]-'0');
                ans[i+j+1] = res%10 + '0';  // ones place of multiplication result
                ans[i+j] += res/10;         // carry over to previous index if result >= 10
            }
        }
        if(ans[0] == '0') return ans.substr(1);
        return ans;
    }
};,63,https://leetcode.com/problems/multiply-strings,https://leetcode.com/problems/multiply-strings/solutions/1563536/c-simple-solution-w-explanation-and-images-school-optimized-multiplication/,17,43,cpp

class Solution {
public:
    void solve(vector<int>& nums, vector<vector<int>>& ans, int i){
        if(i >= nums.size()){
            ans.push_back(nums);
            return;
        }

        for(int j=i; j<nums.size(); j++){
            swap(nums[i], nums[j]);
            solve(nums, ans, i+1);
            swap(nums[i], nums[j]);
        }
    }

    vector<vector<int>> permuteUnique(vector<int>& nums) {
        vector<vector<int>> ans;
        int i = 0;
        solve(nums, ans, i);
        set<vector<int>> temp;
        for(auto it : ans){
            temp.insert(it);
        }
        vector<vector<int>> finalAnswer;
        for(auto it : temp){
            finalAnswer.push_back(it);
        }
        return finalAnswer;
    }
};,37,https://leetcode.com/problems/permutations-ii,https://leetcode.com/problems/permutations-ii/solutions/4347381/easy-understandable-c-solution/,18,47,cpp

