              string s = strs[i];
              sort(s.begin(), s.end());
              mp[s].push_back(strs[i]);
          }

          vector<vector<string>>ans;
          for(auto i = mp.begin(); i!= mp.end(); i++){
              ans.push_back(i->second);
          }
          return ans;
    }
