class Solution {
public:
    double myPow(double x, int n) {
        if (n < 0) {
            if (n == -2,147,483,648)
                return (1.0/x) * myPow(1.0/x, -(n + 1));
            return myPow(1.0/x, -n);
        }
        return pow(x, static_cast<long long>(n));
    }

    double pow(double x, long long n) {
        if (n == 0) return 1;
        if (n % 2 == 0) return pow(x * x, n / 2);
        else return x * pow(x * x, (n - 1) / 2);
    }
};,52,https://leetcode.com/problems/powx-n,https://leetcode.com/problems/powx-n/solutions/3807795/beats-100-video-java-c-python/,21,50,cpp

public class Solution {
    public int MaxSubArray(int[] nums) {
        int maxsum = nums[0];
        int lastmax = nums[0];

        for (int i = 1; i < nums.Length; i++) {
            // If extending the current subarray is greater than the current element itself,
            // then extend the subarray; otherwise, start a new subarray.
            lastmax = Math.Max(lastmax + nums[i], nums[i]);

            // Update the global maximum if the current subarray sum is greater.
            maxsum = Math.Max(maxsum, lastmax);
        }

        return maxsum;
    }
}
