/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode * reverse(ListNode* start, ListNode* end){
        ListNode * p = NULL, *q = NULL, *r = start;
        while(r != end){
            p = q;
            q = r;
            r = r->next;

            q->next = p;
        } 
        return q;
    }
    ListNode* reverseBetween(ListNode* head, int left, int right) {

        if(head== NULL || head->next == NULL){
            return head;
        }

        // startHead points to left node prev
        ListNode *startHead = head,* startPrev = NULL;
        int l = 1;
        while(l < left){
            startPrev = startHead;
            startHead = startHead->next;

            l++;
        }

        // endCurr points to right node 
        ListNode * endCurr = head;
        int r = 1;

        while(r<right){
            endCurr = endCurr->next;
            r++;
        }

        ListNode* endNext = endCurr->next;



        ListNode * temp = reverse(startHead, endCurr->next);

        // for case like [3,5] , l = 1 , r = 1 (when l = 1 startPrev = NULL)
        if(l!=1){
            startPrev->next = temp;
        }
        else{
            head = temp;
        }


        startHead->next = endNext;

        return head;
    }
