        if(i==n-1)
            return triangle[i][j];

        if(dp[i][j] != -1)
            return dp[i][j];

        int first = triangle[i][j] + solveMemoization(triangle, i+1, j, n, dp);
        int second = triangle[i][j] + solveMemoization(triangle, i+1, j+1, n, dp);

        dp[i][j] = min(first, second);
        return dp[i][j];
    }

public:
    int minimumTotal(vector<vector<int>>& triangle) {
        int n=triangle.size();
        vector<vector<int>> dp(n+1, vector<int> (n+1, -1));
        int ans = solveMemoization(triangle, 0, 0, n, dp);
        return ans;
    }
