public:
    int robber(vector<int>& nums, int pos, int last, int end, vector<vector<int>>& dp){
        if(pos == end) return 0; 

        int k1 = 0, k2 = 0; int t = last; if(t == -1) t = nums.size(); 

        if(dp[pos+1][t] == -1) dp[pos+1][t] = robber(nums, pos+1, last, end, dp); 
