        if(dp[pos+1][pos] == -1) dp[pos+1][pos] = robber(nums, pos+1, pos, end, dp);
        if(last == -1 || last+1 != pos) k2 = nums[pos] + dp[pos+1][pos]; 

        return max(k1, k2); 

    }



    int rob(vector<int>& nums) {

        if(nums.size() == 1) return nums[0]; 

        if(nums.size() == 2) return max(nums[0], nums[1]); 

        vector<vector<int>> dp(nums.size()+2, vector<int>(nums.size()+1, -1)); 
        vector<vector<int>> dp1(nums.size()+2, vector<int>(nums.size()+1, -1)); 

        int k1 = 0, k2 = 0; 

        k1 = robber(nums, 1, 0, nums.size()-1, dp) + nums[0];



        k2 = robber(nums, 1, -1, nums.size(), dp1); 

        return max(k1, k2);  

        // return -1; 

