                {
                    int ans = dp[i-coins[j]];
                    dp[i] = min(dp[i], ans+1);

                }
            }
        }

        return dp[amount];

    }

public:
    int coinChange(vector<int>& coins, int amount) {

        int ans = solveTabulation(coins, amount);

        if(ans==INT_MAX)
            return -1;

        return ans;
    }
