class Solution {
public:
    int coinChange(vector<int>& coins, int n) {
        // creating the base dp array, with first value set to 0
        int dp[++n];
        dp[0] = 0;
        // more convenient to have the coins sorted
        sort(begin(coins), end(coins));
        // populating our dp array
        for (int i = 1; i < n; i++) {
            // setting dp[0] base value to 1, 0 for all the rest
            dp[i] = INT_MAX;
            for (int c: coins) {
                if (i - c < 0) break;
                // if it was a previously not reached cell, we do not add use it
                if (dp[i - c] != INT_MAX) dp[i] = min(dp[i], 1 + dp[i - c]);
            }
        }
        return dp[--n] == INT_MAX ? -1 : dp[n];
    }
};,157,https://leetcode.com/problems/coin-change,https://leetcode.com/problems/coin-change/solutions/778548/c-dp-solution-explained-100-time-100-space/,111,322,cpp

class Solution {
    public List<String> findItinerary(List<List<String>> tickets) {
        return util1(tickets);
    }
    public List<String> util1(List<List<String>> tickets) {
        HashMap<String, TreeMap<String, Integer>> hm = constGraph(tickets);
        ans = new LinkedList<>();
        dfs(hm, "JFK");
        return ans;
    }

    public void dfs(HashMap<String, TreeMap<String, Integer>> hm, String start) {
        TreeMap<String, Integer> tm = hm.get(start);
        while (tm.size() != 0) {
            String nextNode = tm.firstKey();
            tm.put(nextNode, tm.get(nextNode) - 1);
            if (tm.get(nextNode) == 0) {
                tm.remove(nextNode);
            }
            dfs(hm, nextNode);
        }
        ans.addFirst(start);
    }

    LinkedList<String> ans;

    public HashMap<String, TreeMap<String, Integer>> constGraph(List<List<String>> tickets) {
        HashMap<String, TreeMap<String, Integer>> hm = new HashMap<>();
        for (List<String> ls : tickets) {
            String node1 = ls.get(0);
            String node2 = ls.get(1);
            if (hm.containsKey(node1)) {
                TreeMap<String, Integer> t = hm.get(node1);
                t.put(node2, t.getOrDefault(node2, 0) + 1);
            } else {
                TreeMap<String, Integer> t = new TreeMap<>();
                t.put(node2, 1);
                hm.put(node1, t);
            }

            if (hm.containsKey(node2) == false) {
                hm.put(node2, new TreeMap<>());
            }
        }
        return hm;
    }
} 
