class Solution {
public:

    // function for finding maximum subarray having sum less than k

    int find_max(vector<int>& arr, int k)
    {
        int n = arr.size();

        int maxi = INT_MIN;

        // curr_sum will store cumulative sum

        int curr_sum = 0;

        // set will store the prefix sum of array

        set<int> s;

        // put 0 into set, if curr_sum == k, (curr_sum - k) will be zero 

        s.insert(0);

        for(int i = 0; i < n; i++)
        {
            // calculate cumulative sum

            curr_sum += arr[i];

            // find the prefix sum in set having sum == curr_sum - k

            auto it = s.lower_bound(curr_sum - k);

            // if prefix sum is present, update the maxi

            if(it != s.end())
            {
                maxi = max(maxi, curr_sum - *it);
            }

            // insert prefix sum into set

            s.insert(curr_sum);
        }

        return maxi;
    }

    int maxSumSubmatrix(vector<vector<int>>& matrix, int k) {

        int n = matrix.size();

        int m = matrix[0].size();

        int maxi = INT_MIN;

        // fix the position of two rows and take cumulative sum of columns between two fixed rows

        for(int start_row = 0; start_row < n; start_row++)
        {
            vector<int> col_array(m, 0);

            for(int end_row = start_row; end_row < n; end_row++)
            {
                // take cumulative sum of columns between two fixed rows

                for(int col = 0; col < m; col++)
                {
                    col_array[col] += matrix[end_row][col];
                }

                // find maximum subarray having sum less than equal to k

                int curr_max = find_max(col_array, k);

                // update the maximum sum

                maxi = max(maxi, curr_max);
            }
        }

        return maxi;
    }
};,23,https://leetcode.com/problems/max-sum-of-rectangle-no-larger-than-k,https://leetcode.com/problems/max-sum-of-rectangle-no-larger-than-k/solutions/2488222/faster-easy-to-understand-c-code/,117,363,cpp

class Solution {
public:
    unordered_map<int, vector<int>> dp;
    vector<int> largestDivisibleSubset(vector<int>& nums) {
        sort(begin(nums), end(nums));
        vector<int> ans;
        for(int i = 0; i < size(nums); i++) {
            auto res = solve(nums, i);
            if(size(res) > size(ans)) ans = res;
        }
        return ans;
    }
    vector<int> solve(vector<int>& nums, int start) {
        if(start >= size(nums)) return {};
        if(dp.count(start)) return dp[start];
        for(int next = start+1; next < size(nums); next++) {
            if(nums[next] % nums[start]) continue;
            auto res = solve(nums, next);
            if(size(res) >= size(dp[start])) dp[start] = res;
        }
        dp[start].push_back(nums[start]);
        return dp[start];
    }
};,63,https://leetcode.com/problems/largest-divisible-subset,https://leetcode.com/problems/largest-divisible-subset/solutions/1578991/c-4-simple-solutions-w-detailed-explanation-optimizations-from-brute-force-to-dp/,118,368,cpp

/** 
 * Forward declaration of guess API.
 * @param  num   your guess
 * @return 	     -1 if num is higher than the picked number
 *			      1 if num is lower than the picked number
 *               otherwise return 0
 * int guess(int num);
 */

class Solution {
public:
    int guessNumber(int n) {

        int st = 1;
        int end = n;

        while(st<=end){
            int mid = st+(end-st)/2;
            int a = guess(mid);
            if(a==0) return mid;
            else if(a<0) end = mid-1;
            else st = mid+1;
        }
        return -1;
    }
