/**
 * Using Reservoir Sampling
 *
 * Suppose the indexes of the target element in array are from 1 to N. You have
 * already picked i-1 elements. Now you are trying to pick ith element. The
 * probability to pick it is 1/i. Now you do not want to pick any future
 * numbers.. Thus, the final probability for ith element = 1/i * (1 - 1/(i+1)) *
 * (1 - 1/(i+2)) * .. * (1 - 1/N) = 1 / N.
 *
 * Time Complexity:
 * 1) Solution() Constructor -> O(1)
 * 2) pick() -> O(N)
 *
 * Space Complexity: O(1)
 *
 * N = Length of the input array.
 */
class Solution {

    int[] nums;
    Random random;

    public Solution(int[] nums) {
        this.nums = nums;
        this.random = new Random();
    }

    public int pick(int target) {
        int idx = -1;
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == target) {
                count++;
                if (random.nextInt(count) == 0) {
                    idx = i;
                }
            }
        }

        return idx;
    }
},64,https://leetcode.com/problems/random-pick-index,https://leetcode.com/problems/random-pick-index/solutions/1493137/java-o-n-pick-o-1-space-or-o-1-pick-o-n-space-two-approaches-reservoir-sampling-or-hashmap/,125,398,java

#define ll long long

class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        ll n = nums.size();
        if (n < k) return -1;

        ll low = 0, high = 0;
        for (auto i: nums) {
            low = max(low, 1ll*i);
            high += i;
        }

        ll res = -1;
        while (low <= high) {
            ll mid = low + (high - low)/2;
            ll cnt = 1;
            ll sum = 0;

            for (auto i: nums) {
                if (sum + i <= mid) sum += i;
                else {
                    sum = i;
                    cnt ++;
                }
            }

            if (cnt > k) low = mid + 1;
            else {
                res = mid;
                high = mid - 1;
            }
        }

        return res;
    }
};,135,https://leetcode.com/problems/split-array-largest-sum,https://leetcode.com/problems/split-array-largest-sum/solutions/3748029/book-allocation-problem-code/,126,410,cpp

