int Solution::countSegments(string s) {
    if (s.length() == 0) {
        return 0;
    }
    size_t i, size = s.length();
    int delC{}, startLeft{0}, startRight=size-1;
    while (s[startLeft] == ' ' && startLeft+1 < size) {
        ++startLeft;
    }
    while (s[startRight] == ' ' && startRight-1 >= 0) {
        --startRight;
    }
    bool found{false};
    if (s[0] != ' ') {
        found = true;
    }
    if (startLeft == 0) {
        startLeft = 1;
    }
    for (i = startLeft; i <= startRight; ++i) {
        if (s[i] == ' ' && s[i-1] != ' ') {
            ++delC;
        }
        if (found == false && s[i] != ' ') {
            found = true;
        }
    }
    if (found == true) {
        ++delC;
    }
    return delC;
}
