function findContentChildren(g, s) {
        g.sort((a, b) => a - b); // sort the children's greed factors in non-decreasing order
        s.sort((a, b) => a - b); // sort the cookie sizes in non-decreasing order
        let contentChildren = 0;
        let i = 0; // pointer to the current child's greed factor
        let j = 0; // pointer to the current cookie size
        while (i < g.length && j < s.length) {
            if (s[j] >= g[i]) { // if the current cookie can satisfy the current child's greed factor
                contentChildren++;
                i++;
            }
        j++;
    }
    return contentChildren;
