var findMaximizedCapital = (
    distinctProjects,
    initialCapital,
    profits,
    capitals
) => {
    const { PriorityQueue } = require("@datastructures-js/priority-queue");
    const pqMaxProfits = new PriorityQueue({ compare: (a, b) => b - a });

    let capitalProfits = capitals.map((capital, i) => ({
        capital,
        profit: profits[i],
    }));
    capitalProfits.sort((a, b) => a.capital - b.capital || b.profit - a.profit);
    let availableCapital = initialCapital;

    let p = 0; // project counter
    while (distinctProjects--) {
        while (
            p < capitalProfits.length &&
            capitalProfits[p].capital <= availableCapital
        ) {
            pqMaxProfits.enqueue(capitalProfits[p].profit);
            p++;
        }
        if (!pqMaxProfits.isEmpty()) {
            availableCapital += pqMaxProfits.dequeue();
        } else {
            break;
        }
    }
    return availableCapital;
