    public int[] findFrequentTreeSum(TreeNode root) {
        if(root==null){
            int arr[] = new int[0];
            return arr;
        }
        findFrequentTreeSumH(root);
        ArrayList<Integer> arr=new ArrayList<>();
        for(Integer key : map.keySet()){
