        for(int i=0; i<ans.length; i++){
            ans[i]=arr.get(i);
        }
        return ans;
    }
    public void findFrequentTreeSumH(TreeNode root) {
        if(root==null){
            return;
        }
        findFrequentTreeSumH(root.left);
        findFrequentTreeSumH(root.right);
        int sum=root.val;
        if(root.left!=null){
            sum+=root.left.val;
        }
        if(root.right!=null){
            sum+=root.right.val;
        }
        if(map.containsKey(sum)){
            map.put(sum, map.get(sum)+1);
        }else{
            map.put(sum,1);
        }
        root.val=sum;
        max=Math.max(map.get(sum),max);
    }    
