    int findUnsortedSubarray(vector<int>& nums) {
       vector<int> temp = nums;
       sort(temp.begin(), temp.end());

       int n = nums.size();
       int s = -1, e = -1;

       for(int i=0; i<n; i++) {
           if(nums[i] != temp[i] && s == -1) s = i; 
           if(nums[n - i - 1] != temp[n - i - 1] && e == -1) e = n - i - 1; 
       }

       return s == -1 ? 0 : e - s + 1;
    }
