class Solution {
public:
    vector<int> postorder(Node* root) {
       if (!root) return {};
       vector<int> ans;
       stack<Node*> st;
       st.push(root);
       while (!st.empty()) {
           Node* node = st.top();
           st.pop();
           ans.push_back(node->val);
           for (Node* n: node->children) {
               st.push(n);
           }
       } 
       reverse(ans.begin(), ans.end());
       return ans;
    }
