class Solution {
public:
    vector<int> smallestRange(vector<vector<int>>& nums) {
        vector<int> ans;
        int k=nums.size();

        priority_queue<Node*, vector<Node*> , compare> minheap;
        int mini=INT_MAX;
        int maxi=INT_MIN;
        for(int i=0;i<k;i++){
            int ele=nums[i][0];
            maxi=max(maxi,ele);
            mini=min(mini,ele);
            minheap.push(new Node(ele,i,0));
        }
        int ansStart=mini;
        int ansEnd=maxi;

        while(!minheap.empty()){
            Node* temp=minheap.top();
            int ele=temp->data;
            int row=temp->row;
            int col=temp->col;
            minheap.pop();

            mini=ele;
            int curr=maxi-mini;
            int ansrange=ansEnd-ansStart;
            if(curr<ansrange){
                ansStart=mini;
                ansEnd=maxi;
            }
            if(col+1<nums[row].size()){
                maxi=max(maxi,nums[row][col+1]);
                Node* newNode=new Node(nums[row][col+1],row,col+1);
                minheap.push(newNode);
            }
            else
            break;
        }
        ans.push_back(ansStart);
        ans.push_back(ansEnd);
        return ans;
    }
