        string res="";
        string word="";
        int start=0;
        for(int i=0;i<sentence.length();i++){
            if(sentence[i]==' '){
                string ans=checkSuccessor(dictionary,word);
                if(ans==""){
                    res+=word;
                }else{
                    res+=ans;
                }
                word="";
                start=i+1;
                res+=" ";
            }else{
                word+=sentence [i];
            }
        }
        string ans=checkSuccessor(dictionary,sentence.substr(start));
        if(ans==""){
            res+=sentence.substr(start);
        }else{
            res+=ans;
        }


        return res;


    }
