class Solution {
public:

    bool finval(TreeNode* root, int val, TreeNode* bangbang){
        if (root==NULL) return false;
        if (root!=bangbang && root->val==val) return true;
        if (root->val > val) return finval(root->left, val, bangbang);
        return finval(root->right, val, bangbang);
    }

    bool hehe(TreeNode* head, TreeNode* root, int k){
        if (root==NULL) return false;
        bool j = finval(head,k - root->val, root);
        if (j) return true;
        return hehe(head, root->left, k) || hehe(head, root->right, k);
    }

    bool findTarget(TreeNode* root, int k) {
        return hehe(root, root, k);
    }
