/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    TreeNode* insertIntoBST(TreeNode* root, int val) {
        if(root == NULL){
            TreeNode* temp = new TreeNode(val);
            return temp;
        } 

        if(val > root->val && !root->right){
            TreeNode* temp = new TreeNode(val);
            root->right = temp;
            return root;
        }
        else if(val < root->val && !root->left){
            TreeNode* temp = new TreeNode(val);
            root->left = temp;
            return root;
        }
        if(!root->left && !root->right){
            TreeNode* temp = new TreeNode(val);
            if(val > root->val) root->right = temp;
            if(val < root->val) root->left = temp;
            return root;
        }

        if(val < root->val) insertIntoBST(root->left,val);
        else if(val > root->val) insertIntoBST(root->right,val);

        return root;      
    }
};,54,https://leetcode.com/problems/insert-into-a-binary-search-tree,https://leetcode.com/problems/insert-into-a-binary-search-tree/solutions/3982030/easy-solution-using-recursion/,208,784,cpp

