class Solution {
public:
    int minimumDeleteSum(string s1, string s2) {
        int n=s1.length(), m=s2.length();

        vector<vector<int>> dp(n+1,vector<int>(m+1,INT_MAX/2));

        dp[0][0]=0;

        // cost when s2 = ""
        for(int i=1;i<n+1;i++){
            dp[i][0]=dp[i-1][0]+s1[i-1]-'a'+97;
        }

        // cost when s1 = ""
        for(int j=1;j<m+1;j++){
            dp[0][j]=dp[0][j-1]+s2[j-1]-'a'+97;
        }

        for(int i=1;i<n+1;i++){
            for(int j=1;j<m+1;j++){
                if(s1[i-1] == s2[j-1]){
                    dp[i][j]=dp[i-1][j-1]; // cost of subsequence [i,j] = [i-1,j-1]
                }else{
                    int delete_s1 = s1[i-1]-'a'+97 + dp[i-1][j]; // cost of subsequence [i,j] = ASCII(ith char) + [i-1,j]
                    int delete_s2 = s2[j-1]-'a'+97 + dp[i][j-1]; // cost of subsequence [i,j] = ASCII(jth char) + [i,j-1]

                    dp[i][j]=min(delete_s1, delete_s2);
                }
            }
        }
        return dp[n][m];
    }
};,69,https://leetcode.com/problems/minimum-ascii-delete-sum-for-two-strings,https://leetcode.com/problems/minimum-ascii-delete-sum-for-two-strings/solutions/3840812/c-tabulation-similar-to-longest-common-subsequence/,210,712,cpp

