class Solution {
    public int carFleet(int target, int[] position, int[] speed) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((a,b)->(b[0]-a[0]));//sort by position

        int n = position.length;
        for(int i=0; i<n; i++){
           heap.add(new int[]{position[i], speed[i]}); 
        }

        int fleets = 0;
        float lastTime = 0; //time taken by last fleet to reach target
        while(!heap.isEmpty()){
            int[] poll = heap.poll();

            float dist = lastTime * poll[1];
            float distToCover = target - poll[0];

            if(dist < distToCover){//new fleet start
                fleets++;
                lastTime = distToCover/poll[1];
            }
        }
        return fleets;
    }
