class Solution {
public:
    TreeNode* ans;
    int help(TreeNode* root){
        if(!root)return 0;
        int l = help(root->left);
        int r = help(root->right);
        return max(l,r)+1;
    }
    bool help2(TreeNode*root,int ht){
        if(ht==0)
            return true;
        if(!root)return false;
        bool l = help2(root->left,ht-1);
        bool r = help2(root->right,ht-1);
        if(l and r){
            // cout<<root->val<<" ";
            ans = root;
        }
        return l or r;
    }
    TreeNode* subtreeWithAllDeepest(TreeNode* root) {
        int ht=0;
        ht = help(root);
        help2(root,ht);
        return ans;
    }
