class Solution {
public:
    bool isBipartite(int node,vector<int>& isVisited,vector<int> adj[]){
        isVisited[node]=1;
        queue<pair<int,int>> q;
        q.push({node,1});
        while(!q.empty()){
            auto front=q.front();
            int currNode=front.first;
            int color=front.second;
            int adjColor=(color==1)?2:1;
            q.pop();
            for(auto i:adj[currNode]){
                if(!isVisited[i]){
                    q.push({i,adjColor});
                    isVisited[i]=adjColor;
                }
                else if(isVisited[i]==color){
                    return true;
                }
            }
        }
        return false;
    }
    bool possibleBipartition(int n, vector<vector<int>>& dislikes) {
        vector<int> adj[n+1];
        for(auto i:dislikes){
            int u=i[0];
            int v=i[1];
            adj[u].push_back(v);
            adj[v].push_back(u);
        }
        vector<int> isVisited(n+1,0);
        for(int i=1;i<=n;i++){
            if(!isVisited[i]){
                if(isBipartite(i,isVisited,adj)){
                    return false;
                }
            }
        }
        return true;
    }
