class Solution {
public:
    vector<vector<int>> dif2hi;//dif2hi[i][dif]=hi
    int n;
    int calHi(vector<int>& rods, int i, int dif) {
        if (i == n) {
            if (dif == 0) return 0;
            else return INT_MIN;
        }

        if (dif2hi[i][dif]!=-1)            
            return dif2hi[i][dif];

        int hi = calHi(rods, i+1, dif);
        int rod=rods[i];
        //Place the rod on the tailer side
        hi = max(hi, calHi(rods, i+1, dif+rod) + rod);

        //Place the rod on the shorter side
        hi = max(hi, calHi(rods, i+1, abs(dif-rod)) + max(0, rod-dif));  
        return dif2hi[i][dif] = hi;
    }

    int tallestBillboard(vector<int>& rods) { 
        n=rods.size(); 
        //Use Constraint sum(rods[i]) <= 5000
        dif2hi.assign( rods.size(), vector(5001, -1));   
        return calHi(rods, 0, 0);
    }  
};
