class Solution {
    Map<Integer, TreeMap<Integer, PriorityQueue<Integer>>> levelItems; 
    int minIndex, maxIndex;
    public List<List<Integer>> verticalTraversal(TreeNode root) {
        if (root == null) return new ArrayList<>();

        this.levelItems = new HashMap<>();
        this.minIndex = Integer.MAX_VALUE;
        this.maxIndex = Integer.MIN_VALUE;

        dfs(root, 0, 0);

        List<List<Integer>> res = new ArrayList<>();
        for (int i = minIndex; i <= maxIndex; i++) {
            List<Integer> innerList = new ArrayList<>();
            TreeMap<Integer, PriorityQueue<Integer>> treeMap = levelItems.get(i);
            for (int row : treeMap.keySet()) {
                PriorityQueue<Integer> pq = treeMap.get(row);
                while (!pq.isEmpty()) {
                    innerList.add(pq.poll());
                }
            }
            res.add(innerList);
        }
        return res;
    }

    private void dfs(TreeNode node, int row, int col) {
        if (node == null) return;
        minIndex = Math.min(minIndex, col);
        maxIndex = Math.max(maxIndex, col);
        levelItems.computeIfAbsent(col, k -> new TreeMap<>())
                .computeIfAbsent(row, k -> new PriorityQueue<>()).offer(node.val);
        dfs(node.left, row + 1, col - 1);
        dfs(node.right, row + 1, col + 1);
    }
