class Solution {
    public int sumRootToLeaf(TreeNode node, int pre) { // pre is sum of path from root to parent of node
        if (node.left == null && node.right == null) // node is a leaf node, return the sum of path from root to node
            // return pre << 1 | node.val; // also work
            return pre * 2 + node.val;
        int ans = 0;
        if (node.left != null) // node.left is not None, recursively find the sum node to leaf
            // ans += sumRootToLeaf(node.left, pre << 1 | node.val); // also work
            ans += sumRootToLeaf(node.left, pre * 2 + node.val);
        if (node.right != null) // node.right is not None, recursively find the sum node to leaf
            // ans += sumRootToLeaf(node.right, pre << 1 | node.val); // also work
            ans += sumRootToLeaf(node.right, pre * 2 + node.val);
        return ans;
    }

    public int sumRootToLeaf(TreeNode root) {
        return sumRootToLeaf(root, 0);
    }
