var longestArithSeqLength = function(A) {
    const n = A.length;
    if (n <= 1) return n;

    // Initialize a 2D array to store the length of the longest arithmetic sequence
    const dp = new Array(n).fill(null).map(() => new Map());

    let maxLen = 2; // Initialize the maximum length to 2

    // Iterate over the array
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            const diff = A[i] - A[j];

            // If there is a previous element with the same difference, update the length
            if (dp[j].has(diff)) {
                dp[i].set(diff, dp[j].get(diff) + 1);
            } else {
                // Otherwise, initialize the length to 2
                dp[i].set(diff, 2);
            }

            // Update the maximum length
            maxLen = Math.max(maxLen, dp[i].get(diff));
        }
    }

    return maxLen;
};
