    void dfs(int i,int j,vector<vector<int>>& image,vector<vector<bool>>& vis,int hunt,int color)
    {
        if(i<0||j<0||i>=m||j>=n||vis[i][j]||image[i][j]!=hunt)
        return;
        vis[i][j]=true;
        if(i==0||j==0||i>=m-1||j>=n-1)
        {
            image[i][j]=color;
        }
        if((i+1<=m-1 && image[i+1][j]!=hunt && !vis[i+1][j]) || (i-1>=0 && image[i-1][j]!=hunt && !vis[i-1][j]) || (j+1<=n-1 && image[i][j+1]!=hunt && !vis[i][j+1]) || (j-1>=0 && image[i][j-1]!=hunt && !vis[i][j-1]))
        image[i][j] = color;
        dfs(i+1,j,image,vis,hunt,color);
        dfs(i-1,j,image,vis,hunt,color);
        dfs(i,j+1,image,vis,hunt,color);
        dfs(i,j-1,image,vis,hunt,color);
    }
