class Solution {
public:
    int maxSumAfterPartitioning(vector<int>& arr, int k) {
        int n = arr.size();
        vector<int> dp(n+1,-1);
        auto fn = [&](auto&&fn,int id) -> int {
            int mx = 0, ans = 0;
            if(dp[id] != -1) return dp[id];
            for(int i=id; i<min(id+k,n); ++i){
                mx = max(mx,arr[i]);
                ans = max(ans,(i-id+1)*mx + fn(fn,i+1));
            }
            return dp[id] = ans;
        };
        return fn(fn,0);
    }
