var addNegabinary = function (a1, a2) {
  const ans = []
  ans.push_front = ans.unshift
  ans.pop_front = ans.shift
  const m = a1.length
  const n = a2.length
  var carry = 0
  for (var i = m - 1, j = n - 1; i >= 0 || j >= 0; i--, j--) {
    const sum = (a1[i] || 0) + (a2[j] || 0) + carry
    let reminder = sum % -2
    carry = Math.trunc(sum / -2)
    if (reminder === -1) {
      reminder = 1
      carry = 1
    }
    ans.push_front(reminder)
  }
  if (carry === 1) {
    ans.push_front(carry)
  } else if (carry === -1) {
    ans.push_front(1, 1)
  }
  while (ans[0] === 0 && ans.length > 1) {
    ans.pop_front()
  }
  return ans
}
