        while (c > 0) {
            //[idx++ % n] - means that I find index of array to add
            //and then increment this index
            //Math.min(idx, c) - is used because in the end when we have candies left less than we need to add, then just add minimum number
            arr[idx++ % n] += Math.min(idx, c);

            //during loop we need to substract given number of candies
            //above from all number of candies left
            //if this number is negative, then just 0 left.
            c = Math.max(c - idx, 0);
        }
        return arr;
    }
