class Solution {
public:
    bool parseBoolExpr(string str) {
        vector<char> s;
        int f = 0, t = 0,c;
        for(auto &i: str){
            if(i==',')continue;
            if(i==')'){
                f = 0, t = 0;
                c = '#';
                while(s.back() != '('){
                    if(s.back()=='f')f++;
                    else if(s.back()=='t')t++;
                    s.pop_back();
                }
                s.pop_back();
                c = s.back();
                s.pop_back();
                if(c=='#')continue;
                if(c=='|'){
                    // cout<<'|';
                    if(t){
                       s.push_back('t'); 
                    }else{
                        s.push_back('f');
                    }
                }else if(c=='!'){
                    cout<<'!';
                    if(f){
                        s.push_back('t');
                    }else{
                        s.push_back('f');
                    }
                }else{
                    cout<<'&';
                    if(f){
                       s.push_back('f'); 
                    }else{
                        s.push_back('t');
                    }
                }
                // cout<<" "<<s.back()<<" "<<s.size()<<endl;
            }else{
                s.push_back(i);
            }
        }
        return s.back()=='f'?false:true;
    }
