class Solution {
public:
    void bfs(unordered_map<int,vector<int>> &re,unordered_map<int,vector<int>> &be,vector<int> &ans,map<pair<int,int> , int> &vis,int start)
    {
        queue<pair<int,pair<int,int>>> q; // node, length,color
        q.push({0,{0,start}});

        while(!q.empty())
        {
            int sz = q.size();
            for(int i=0;i<sz;i++)
            {
                int x = q.front().first;
                int y = q.front().second.first;
                int z = q.front().second.second;
                q.pop();
                vis[{x,1-z}] = 1;
                if(ans[x] == -1)
                    ans[x] = y;

                if(z && re[x].size()>0)
                {
                    for(int i: re[x]){
                        if(vis.find({i,z}) == vis.end()){
                            q.push({i,{y+1,1-z}});
                        }

                    }
                }
                if(!z && be[x].size()>0)
                {
                    for(int i: be[x]){
                        if(vis.find({i,z}) == vis.end()){
                            q.push({i,{y+1,1-z}});
                        }

                    }
                }
            }
        }
    }


    vector<int> shortestAlternatingPaths(int n, vector<vector<int>>& redEdges, vector<vector<int>>& blueEdges) {
        unordered_map<int,vector<int>> re,be;

        for(auto &i: redEdges)
        {
            re[i[0]].push_back(i[1]);
        }

        for(auto &i: blueEdges)
        {
            be[i[0]].push_back(i[1]);
        }

        map<pair<int,int> , int> vis,vis2;

        vector<int> ans(n,-1),ans2(n,-1),res(n,-1);
        int start = 0; // blue;
        bfs(re,be,ans,vis,start);
        bfs(re,be,ans2,vis2,1-start);

        for(int i=0;i<n;i++)
        {
            if(ans[i]!=-1 && ans2[i]!=-1)
                res[i] = min(ans[i],ans2[i]);
            else
            {
                if(ans[i]!=-1)
                    res[i] = ans[i];
                else
                    res[i] = ans2[i];
            }
        }
        return res;

    }
