class Solution {
public:
    string minRemoveToMakeValid(string s) {
        int n = s.length();
        vector<int> pair(n,0);
        stack<int> open;

        for(int i=0; i<n; i++){
            if(s[i]=='('){
                open.push(i);
            }
            else if(s[i]==')'){
                if(!open.empty() && s[open.top()] =='('){ 
                    int j = open.top();
                    pair[i] = j;
                    pair[j] = i;
                    open.pop();
                }
                else 
                    open.push(i);
            }
        }

        while(!open.empty()){
            pair[open.top()] = -1;
            open.pop();
        }

        string ans;
        for(int i=0; i<n; i++){
            if(pair[i] >= 0)
                ans += s[i];
        }
        return ans;
    }
