class Solution {
public:
    unordered_map<int, unordered_map<string, int>>dp;
    int helper(vector<string>& words, int curr, vector<char> letters, vector<int>& score, string memory){
        if(curr<0)return 0;
        if(dp[curr][memory]!=0)return dp[curr][memory];
        unordered_map<char, int>curr_dict, curr_word, remaining;
        vector<char>lettersr;
        for(int i=0;i<letters.size();i++){
            curr_dict[letters[i]]++;
        }
        for(int i=0;i<words[curr].size();i++){
            curr_word[words[curr][i]]++;
        }
        remaining=curr_dict;
        int flag=1;
        for(auto temp:curr_word){
            if(curr_dict[temp.first]<temp.second){
                flag=0;
                break;
            }
            remaining[temp.first]-=temp.second;
        }
        string a="", b="";
        for(int i=0;i<letters.size();i++){
            a+=letters[i];
        }
        for(int i=0;i<remaining.size();i++){
            b+=remaining[i];
        }
        sort(a.begin(), a.end());
        sort(b.begin(), b.end());
        if(flag==0){
            return helper(words, curr-1, letters, score, a);
        }
        int curr_score=0;
        for(int i=0;i<words[curr].size();i++){
            curr_score+=score[words[curr][i]-'a'];
        }
        for(auto temp:remaining){
            for(int i=0;i<temp.second;i++)
                lettersr.emplace_back(temp.first);
        }
        int ans2=helper(words, curr-1, lettersr, score, b)+curr_score;        
        return max(helper(words, curr-1, letters, score, a), ans2);
    }
    int maxScoreWords(vector<string>& words, vector<char>& letters, vector<int>& score) {
        string a="";
        for(int i=0;i<letters.size();i++){
            a+=letters[i];
        }
        sort(a.begin(), a.end());
        return helper(words, words.size()-1, letters, score,a);        
    }
};,57,https://leetcode.com/problems/maximum-score-words-formed-by-letters,https://leetcode.com/problems/maximum-score-words-formed-by-letters/solutions/2720114/c-dp-easy/,316,1381,cpp

class Solution {
public:
    void solve(int i,int &n,vector<int> &v,vector<int> &score,int &ans,int sum,vector<string> &words){
        ans = max(ans,sum);
        if(i>=n)return;
        vector<int> tmp = v;
        int j=0,sum1=0;
        for(j = 0; j < words[i].length(); j++){
            tmp[words[i][j]-'a']--;
            sum1 += score[words[i][j]-'a'];
            if(tmp[words[i][j]-'a']<0)break;
        }
        if(j==words[i].length()){
            solve(i+1,n,tmp,score,ans,sum+sum1,words);
        }
        solve(i+1,n,v,score,ans,sum,words);
    }
    int maxScoreWords(vector<string>& words, vector<char>& letters, vector<int>& score) {
        vector<int> v(26,0);
        for(auto &i: letters){
            v[i-'a']++;
        }
        int ans = 0,n=words.size();
        solve(0,n,v,score,ans,0,words);
        return ans;
    }
