/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    // declare sum field to store result
    int sum = 0;
    // declare levelSum to hold sum of leaves of each level
    int levelSum = 0;
    public int deepestLeavesSum(TreeNode root) {
        // declare queue
        Queue<TreeNode> que = new LinkedList();
        // add current root to queue
        que.add(root);
        // start breadth first search until queue is not empty
        while(!que.isEmpty()) {
            // get current level nodes count
            int currentLevelNodes = que.size();
            // iterate over nodes:
            for(int i = 0; i < currentLevelNodes; i++) {
                // on each iteration get node from queue
                TreeNode node = que.remove();
                // check if it is a leaf:
                if(node.left == null && node.right == null) {
                    // add value of node to levelSum
                    levelSum += node.val;
                }
                // check if node.left has link to node:
                if(node.left != null) {
                    // add to queue left node
                    que.add(node.left);
                }
                // check if node.right has link to node
                if(node.right != null) {
                    // add to queue right node
                    que.add(node.right);
                }
            }
            // set current levelSum to sum
            sum = levelSum;
            // set levelSum to zero
            levelSum = 0;
        }
        // return sum
        return sum;
    }
