public:
int solve(int i,int &n,int &d,vector<int> &v,vector<int> &dp){
    if(i>=n || i<0)return 0;
    if(dp[i] != -1)return dp[i];
    int a = 0, b = 0;
    for(int j = i+1; j < min(n,i+d+1); j++){
        if(v[j] < v[i]){
            a = max(a,solve(j,n,d,v,dp));
        }else{
            break;
        }
    }
    for(int j = i-1; j >= max(0,i-d); j--){
        if(v[j] < v[i]){
            a = max(a,solve(j,n,d,v,dp));
        }else{
            break;
        }
    }
    return dp[i] = max(a,b)+1;
}
