typedef pair<int,pair<int,int>> pi;
class Solution {
public:
    int minJumps(vector<int>& arr) {
        int n=arr.size();
        unordered_map<int,vector<int>> mp;
        for(int i=0;i<n;i++)
        {
            mp[arr[i]].push_back(i);
        }
        queue<pi> q;
        q.push({arr[0],{0,0}});
        vector<int> vis(n,0);
        vis[0]=1;
        while(!q.empty())
        {
            int x=q.front().first;
            int ind=q.front().second.first;
            int cnt=q.front().second.second;
            vis[ind]=1;
            if(ind==n-1)
                return cnt;
            q.pop();
            if(ind-1>=0 and !vis[ind-1])
            {
                 q.push({arr[ind-1],{ind-1,cnt+1}});
                vis[ind-1]=1;
            }
            if(ind+1<n and !vis[ind+1])
            {
                   q.push({arr[ind+1],{ind+1,cnt+1}});
                   vis[ind+1]=1;
            }
            for(int y:mp[x])
            {
                if(y!=ind and !vis[y])
                {
                    q.push({arr[y],{y,cnt+1}});
                    vis[y]=1;
                }
            }
            mp.erase(x);
         }
        return -1;
    }
