               int pos = -grid[x][y];
               q.pop();

               if(x == m-1 && y == n-1)
               return true;

               // 0  -> Left       
               if(y-1>=0)
               {
                   if(grid[x][y-1] > 0 && mp[pos][0][grid[x][y-1]])
                   {
                       q.push({x,y-1});
                       grid[x][y-1] = -grid[x][y-1];
                   }               
                }   

               // 1  -> Right
               if(y+1 < n)
               {
                   if(grid[x][y+1] > 0 && mp[pos][1][grid[x][y+1]])
                   {
                       q.push({x,y+1});
                       grid[x][y+1] = -grid[x][y+1];
                   }               
                }   

               // 2   -> Up
               if(x-1>=0)
               {
                   if(grid[x-1][y] > 0 && mp[pos][2][grid[x-1][y]])
                   {
                       q.push({x-1,y});
                       grid[x-1][y] = -grid[x-1][y];
                   }
               }   

               // 3   ->  Down     
               if(x+1<m)
               {
                   if(grid[x+1][y] > 0 && mp[pos][3][grid[x+1][y]])
                   {
                       q.push({x+1,y});
                       grid[x+1][y] = -grid[x+1][y];
                   }               
                }   
        }

        return false;
    }
