class UndergroundSystem {
public:
    UndergroundSystem() {}

    void checkIn(int id, string stationName, int t) {
        CheckIn[id] = {stationName, t};
    }

    void checkOut(int id, string stationName, int t) {
        string route = CheckIn[id].first + '_' + stationName;
        Routes[route].first += t - CheckIn[id].second;
        Routes[route].second++;
        CheckIn.erase(id);
    }

    double getAverageTime(string startStation, string endStation) {
        string route = startStation + '_' + endStation;
        return Routes[route].first / (double)Routes[route].second;
    }

private:
    // route: <total time, count>
    unordered_map<string, pair<int, int>> Routes;
    // id: <start station, check-in time>
    unordered_map<int, pair<string, int>> CheckIn;
};

