class Solution {
public:
    int maxSatisfaction(vector<int>& s) {
        int n = s.size(), i = 0;
        sort(s.begin(), s.end());

        int ans = 0, sum = 0;

        for(int i = 0;i<n;i++) sum+= s[i]*(i+1); // find initail cofficient by taking each dish
        for(int i = n-2;i>=0;i--) s[i]+=s[i+1];  // take reverse prefix sum

        i = 0;

		// this is similar to removing commulative sum from original until it increases if the number are -ve.
        while(i<n){
            ans = sum;
            sum-=s[i++];
            if(sum>ans) ans = sum;
            else break;
        }
        return ans;
    }
};
