class Solution {
public:
    // Function to find the maximum score
    int maxScore(string s) {
        // Count the number of '1's in the given string
        int one = count(s.begin(), s.end(), '1');

        int zero = 0;
        int ans = 0;

        // Loop through the string, excluding the last character
        for (int i = 0; i < s.size() - 1; i++) {
            // If the current character is '1', decrement the count of 'one'
            if (s[i] == '1')
                one--;
            else // If the current character is '0', increment the count of 'zero'
                zero++;

            // Calculate the maximum score by adding the counts of 'zero' and 'one'
            ans = max(zero + one, ans);
        }

        // Return the maximum score obtained
        return ans;
    }
};



