//basic nCr function
int nCr(int n, int r) {
    if (r > n) return 0;
    int result = 1;
    // Calculate n*(n-1)*...*(n-r+1)
    for (int i = 0; i < r; i++) {
        result *= (n - i);
    }
    // Calculate r!
    for (int i = 2; i <= r; i++) {
        result /= i;
    }
    return result;
}

