class Solution {
public:
    int longestAwesome(string s) {
        vector<int> m(1 << 10, -2); //{mask, idx}
        m[0] = -1;

        int ans = 0;
        int state = 0;
        for(int i = 0; i < s.length(); i++) {
            int mask = (1 << (s[i] - '0'));
            state ^= mask;

            if(m[state] != -2) {
                int j = m[state];
                ans = max(ans, i - j);
            }

            for(int odd = 0; odd < 10; odd++) {
                mask = (1 << odd);
                if(m[state ^ mask] != -2) {
                    int j = m[state ^ mask];
                    ans = max(ans, i - j);
                }
            }

            // to maximize length update the value at occurrence mask index only once
            // if we update the vlaue at occurrence mask index more than once it will update the previous value leading to inaccurate result 
            if(m[state] == -2) {
                m[state] = i;
            }
        }

        return ans;
    }
