class Solution {
public:
    int countRoutes(vector<int>& locations, int start, int finish, int fuel) {
        const int n = locations.size();
        dp.resize(fuel + 1, vector<int>(n, -1));  // Initialize the memoization table

        return solve(start, finish, fuel, locations);  // Call the solve function
    }
private:
    vector<vector<int>> dp;  // Memoization table to store intermediate results
    const int kMod = 1e9 + 7;  // Constant to perform modulo operation
    int solve(int currCity, int endCity, int fuel, const vector<int>& locations){
        if(fuel < 0) return 0;  // If fuel is negative, return 0 (no valid routes)
        if(~dp[fuel][currCity])  // If the result for the current state is already computed
            return dp[fuel][currCity];  // Return the precomputed result

        int ans = (currCity == endCity);  // Initialize the answer with 1 if we reached the end city, 0 otherwise
        for(int nextCity = 0; nextCity < locations.size(); ++nextCity)
            if(nextCity != currCity){
                ans = (ans + solve(nextCity, endCity, fuel - abs(locations[currCity] - locations[nextCity]), locations)) % kMod;
                // Recursively calculate the number of routes by moving to the next city
                // Update fuel by subtracting the distance between the current city and the next city
                // Add the result to the answer and take modulo to avoid overflow
            }
        return dp[fuel][currCity] = ans;  // Store the computed result in the memoization table and return the answer
    }
};
