class Solution {
    public int[] countSubgraphsForEachDiameter(int n, int[][] edges) {
        int[][] dp  = new int[n][n];
        for  (int i = 0; i <  n; i++) {
            Arrays.fill(dp[i],n);
        }
        for (int[] edge : edges) {
            dp[edge[0] - 1][edge[1] - 1] = dp[edge[1] - 1][edge[0] - 1] = 1;
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    dp[i][j] = Math.min(dp[i][j],dp[i][k] + dp[k][j]);
                }
            }
        }
        int[] res = new int[n - 1];
        for (int state = 0; state < (1 << n); state++) {
            int d = helper(state,dp,n);
            if (d > 0) res[d - 1] += 1;
        }
        return res;
    }

    public int helper(int state,int[][] dp, int n) {
        int city = 0;
        int edge = 0; 
        int res = 0;
        for (int i = 0; i < n; i++) {
            if (((state >> i) & 1) == 0) continue;
            city++;
            for (int j = i + 1; j < n; j++) {
            if (((state >> j) & 1) == 0) continue;
            edge = edge + (dp[i][j] == 1 ? 1 : 0);
            res = Math.max(res,dp[i][j]);
            }
        }
        if (edge != city - 1) return 0;
        return res;
    }
