class Solution {
public:
    int maxWidthOfVerticalArea(vector<vector<int>>& points) {
        set<int> xCoordinates; // Using a set to store unique x-coordinates

        for (const auto& point : points) {
            xCoordinates.insert(point[0]); // Inserting x-coordinates into the set
        }

        int maxDiff = 0;
        int prevX = INT_MIN;

        for (int x : xCoordinates) {
            if (prevX != INT_MIN) {
                maxDiff = max(maxDiff, x - prevX); // Calculate the maximum difference
            }
            prevX = x;
        }

        return maxDiff;
    }
};


