class Solution {
public:
    int mod = 1000000007;
    int solve(int targetindex, int wordindex,vector<string>& w, string &t,vector<vector<long long int>> &cache,vector<vector<long long int>> &freq)
    {
        if(targetindex >= t.length())
            return 1;
        if(wordindex >= w[0].length())
        {
            return 0;
        }

        if(wordindex >= freq.size())
        {
            return 0;
        }

        if(cache[targetindex][wordindex]!=-1)
            return cache[targetindex][wordindex];

        long long int notpick = solve(targetindex,wordindex+1,w,t,cache,freq)%mod;
        long long int pick = 0;
        int cha = t[targetindex]-'a';
        if(freq[wordindex][cha]!=0){
         pick = (freq[wordindex][cha]%mod)*(long long int)solve(targetindex+1,wordindex+1,w,t,cache,freq)%mod;
        }

        return cache[targetindex][wordindex] = (pick+notpick)%mod;


    }

    int numWays(vector<string>& w, string t) {
        vector<vector<long long int>> cache(t.size(),vector<long long int> (w[0].size(),-1));
        vector<vector<long long int>> freq(w[0].size(),vector<long long int> (26,0));

        for(int i=0;i<w.size();i++)
        {
            for(int j=0;j<w[0].size();j++)
            {
                freq[j][w[i][j]-'a']++;
            }
        }
        return solve(0,0,w,t,cache,freq);
    }
