    public boolean closeStrings(String w1, String w2) {
        char[] c1 = w1.toCharArray();
        char[] c2 = w2.toCharArray();
        for(int i=0;i<c1.length&&i<c2.length;i++){
            if(w1.indexOf(c2[i])==-1){
                return false;
            }
        }
        Arrays.sort(c1);
        Arrays.sort(c2);
        if(Arrays.equals(c1, c2)){
            return true;
        }

        int arr1[]=count(c1);
        int arr2[]=count(c2);
        if(Arrays.equals(arr1, arr2)){
            return true;
        }
        return false;
    }
