#include <list>

class FrontMiddleBackQueue {
public:
    std::list<int> ml;

    FrontMiddleBackQueue() {
    }

    void pushFront(int val) {
        ml.push_front(val);
    }

    void pushMiddle(int val) {
        std::list<int>::iterator it = ml.begin();
        std::advance(it, ml.size() / 2);
        ml.insert(it, val);
    }

    void pushBack(int val) {
        ml.push_back(val);
    }

    int popFront() {
        if (ml.empty()) {
        return -1;
    }
        int ans = ml.front();
        ml.pop_front();
        return ans;
    }

    int popMiddle() {
        if (ml.empty()) {
        return -1;
    }

    list<int>::iterator it = ml.begin();
    advance(it, ml.size() / 2);
    if (ml.size() % 2 == 0) {
        advance(it, -1);
    }
    int ans = *it;
    ml.erase(it);
    return ans;
    }

    int popBack() {
        if (ml.empty()) {
        return -1;
    }
        int ans = ml.back();
        ml.pop_back();
        return ans;
    }
};
