class Solution {
    public int maximumWealth(int[][] accounts) {
        // declare max sum
        int max = 0;
        // iterate over each account
        for(int[] account: accounts) {
            // declare curr sum
            int curr = 0;
            // iterate over each money in account
            for(int money: account) {
                // add money to curr sum
                curr += money;
            }
            // set to max, max of max or curr
            max = Math.max(max, curr);
        }
        // return max
