class Solution {
public:
    int findParent(int node,vector<int> &parent)
    {
        if(node==parent[node])
        return node;

        return parent[node]=findParent(parent[node],parent);
    }
    void Union(int x,int y,vector<int> &parent,vector<int> &rank)
    {
        x=findParent(x,parent);
        y=findParent(y,parent);

        if(x==y)
        return;

        if(rank[x]<rank[y])
        {
            parent[x]=y;
        }
        else if(rank[y]<rank[x])
        {
            parent[y]=x;
        }
        else
        {
            parent[x]=y;
            rank[y]++;
        }
    }
    int minimumHammingDistance(vector<int>& s, vector<int>& t, vector<vector<int>>& as) {
        int n=s.size();
        vector<int> parent(n);
        vector<int> rank(n,0);
        for(int i=0;i<n;i++)
        {
            parent[i]=i;
        }
        for(int i=0;i<as.size();i++)
        {
            int x=as[i][0];
            int y=as[i][1];
            Union(x,y,parent,rank);
        }
        map<int,map<int,int>> store;
        for(int i=0;i<n;i++)
        {
            int x=findParent(i,parent);
            store[x][s[i]]++;
        }
        int hammingDis=0;
        for(int i=0;i<n;i++)
        {
            int x=findParent(i,parent);
            if(t[i]==s[i])
            {
                if(store[x][t[i]]>0)
                store[x][t[i]]--;
                else
                hammingDis++;
            }
            else
            {
                if(store[x].find(t[i])!=store[x].end()&&store[x][t[i]]>0)
                {
                    store[x][t[i]]--;
                }
                else
                {
                    hammingDis++;
                }
            }
        }
        return hammingDis;
    }
};,183,https://leetcode.com/problems/minimize-hamming-distance-after-swap-operations,https://leetcode.com/problems/minimize-hamming-distance-after-swap-operations/solutions/2164017/c-easy-to-understand-simple-union-find-approach/,455,1840,cpp

class Solution {
public:
    int largestSubmatrix(vector<vector<int>>& matrix) {
        int m = matrix.size(); // Number of rows in the matrix
        int n = matrix[0].size(); // Number of columns in the matrix
        vector<int> prevRow = vector<int>(n, 0); // Vector to store the previous row
        int ans = 0; // Initialize the maximum area of the largest submatrix

        for (int row = 0; row < m; row++) {
            vector<int> currRow = matrix[row]; // Copy the current row of the matrix

            // Calculate the cumulative sum for each element in the current row
            for (int col = 0; col < n; col++) {
                if (currRow[col] != 0) {
                    currRow[col] += prevRow[col]; // Add the element with its corresponding element in the previous row
                }
            }

            // Sort the elements in the current row in descending order
            vector<int> sortedRow = currRow;
            sort(sortedRow.begin(), sortedRow.end(), greater<int>());

            // Calculate the maximum area of the largest submatrix with consecutive ones
            for (int i = 0; i < n; i++) {
                ans = max(ans, sortedRow[i] * (i + 1)); // Update the maximum area
            }

            prevRow = currRow; // Update the previous row for the next iteration
        }

        return ans; // Return the maximum area of the largest submatrix
    }
};


