class Solution {
public:
    int minimumSize(vector<int>& nums, int k) 
    {
        //we can perform the operations at most k times

        //the final min penalty ans
        long long int ans = LONG_MAX;

        //your penalty is the max number of balls in a bag
        //so according to the given data the min penalty that we can have is min element from the array
        //so according to the given data the max penalty that we can have is max element from the array

        //finding out the min element from the array
        long long int start = 1;
        //finding out the max element from the array
        long long int end = *max_element(nums.begin(),nums.end());

        //taking the approach of range binary search
        while(start <= end)
        {
            long long int mid = (start + ((end - start)/2));

            //now checkin if the mid can be the min penalty

            if(fun(nums,mid,k) == true)
            {
                cout<<"mid = "<<mid<<endl;
                //this is the potential ans
                ans = min(ans,mid);
                //now we will try to minimize the penalty
                end = mid-1;
            }
            else 
            {
                start = mid+1;
            }
        }
        return ans;
    }
    bool fun(vector<int>&nums,long long int &mid,int k)
    {
         long long int count = 0;
         int idx = 0;
         while(idx < nums.size() and k>0)
         {
             if(nums[idx] == mid) 
             {
                 idx++;
             }
             else if(nums[idx] < mid)
             {
                 idx++;
             }
             else if(nums[idx] > mid)
             {
                 if((nums[idx]%mid) == 0)
                 {
                    long long int temp = (nums[idx]/mid);
                    count = (count + (temp-1));
                 }
                 else if((nums[idx]%mid)!=0)
                 {
                     long long int temp = (nums[idx]/mid);
                    count = (count + (temp));
                 }
                 idx++;
             }
             if(count > k) return false;
         }
         return true;
    }
